function demoMain(idx,label){
  var imgs=["nginx:1.25","redis:7","postgres:16"];
  var im=imgs[idx%imgs.length];
  return "["+label+"] ran "+im+": container up 12s, isolated net+fs, exit 0 on stop";
}

